// Ordered by prerequisite. Stable drill IDs preserve prior results.
const Stages = [
  {name:"Read the hive",reason:"Start with the six spaces around a queen. Then learn which pieces can reach them and how to take that freedom away."},
  {name:"Develop your pieces",reason:"Use pins and movement routes to decide where your queen and reserves belong in the opening."},
  {name:"Defend and free pieces",reason:"First protect a liberty or escape. Then change the connections that keep a defender or attacker pinned."},
  {name:"Take the initiative",reason:"Count the pieces that can join a fight. Use that count to compare placements, combine threats and time a counterattack."},
  {name:"Resolve the endgame",reason:"When few moves remain, check who must move, whether either side can force a win and which spaces the queens share."},
  {name:"Optional expansions",reason:"Apply mobility, route planning and queen defence to the Mosquito, Ladybug and Pillbug."}
];
const readCourse = (id,name,summary,principle,watch,ids,icon,color) => ({id,name,summary,principle,watch,ids,icon,color});
const topics = [
  ...BasicCourses,
  readCourse("opening","Queen placement","Choose the shape of the opening.","Trace the line through the first two bugs. A queen placed off that line creates an elbow. Filling its inside can later release the first bug.","The second queen placement decides whether the queens bend towards one another or towards opposite sides.",["elbow","cOpening","zOpening"],"board","sage"),
  readCourse("place","Purposeful placement","Work back from a future destination.","Before committing a reserve piece, trace its first useful move. Hoppers need a straight line. Spiders need a route of exactly three slides.","Check the route again after the opponent replies. A newly placed piece has to wait a turn.",["placeG","placeS","placeG2","placeS2"],"target","blue"),
  readCourse("hop","The hop around","Find a landing that sets up a second jump.","A hopper that misses its target on every current line may reach it in two jumps. Start at the target and look for a pivot on another line.","The opponent gets a turn between jumps. Consider a pin on the pivot or a change to the landing space.",["pivot","pivot2","pivot3","hopReply"],"board","peach"),
  readCourse("block","The block","Close an approach to a queen liberty.","A gate can keep a sliding attacker out while leaving an empty space beside your queen. Test the attacker's entire route around the hive.","An open liberty protected from an ant can still be reached by a hopper or a beetle.",["block","block2","block3","trap1","trap2","trap3","trap4","gateChoice"],"shield","sage"),
  readCourse("fill","The fill","Build a pocket to release a pinned piece.","A pinned bug connects two branches. Complete a chain around it and those branches can still touch when it leaves.","After tracing the new connection, test the released piece's own movement. A hopper needs a jump line and a beetle needs a legal step.",["fillG","fillB","fillG2","fillG3","fillA1","fillA2","fillA3","unpin1","unpin2","unpin3"],"layers","lilac"),
  readCourse("rings","Making a ring","Check who gains mobility from a loop.","Closing a loop can release several pieces in one turn. Mentally remove them one by one and check what stays connected.","Recheck enemy pieces before closing the ring. The opponent gets the first chance to break it.",["ring","ringChoice"],"surround","blue"),
  readCourse("strength","Count attackers","Match available bugs to the remaining spaces.","Count the empty sides, the attackers that can reach them, the reserves that can join, and the pieces you could release. A bug holding a side already may add nothing by moving.","Two ants that can reach the same single gap still leave a gated gap unsolved.",["strength1","strength2"],"chart","sage"),
  readCourse("entries","Control placement","Choose the pin that also denies a reserve entry.","Two placements of a pinning ant may immobilise the same bug. Their contact with empty cells can change where the opponent may deploy.","Look for a useful enemy placement site before choosing a pin. A friendly bug touching that site can deny it to the opponent.",["deny","replace1","replace2","replace3","replace4","replacePin"],"pin","lilac"),
  readCourse("tempo","Tempo and counterattack","Compare racing lines in turns.","Count the turns each side needs, including new placements and approach moves. A move that lifts pressure at home and adds it at the other queen changes both clocks.","Recount after each forcing reply. A shorter attack still loses if the opponent can win this turn.",["counter","counter2","counter3","race","raceDef","twoMove1","twoMove2","twoMove3","twoMove4","twoMove5","twoMove6"],"chart","peach"),
  readCourse("beetles","The two-beetle attack","Give each beetle a separate job.","One beetle can hold the enemy queen while the second covers a defender. The queen stack also supplies friendly contact for a direct drop.","Look at what the lower tile could do if your covering beetle left. A second beetle can spare you that concession.",["pair","pair2","pair3","pairChoice"],"layers","lilac"),
  readCourse("shut","The shutout","Take away the last legal reply.","A shutout requires every movement and every legal reserve placement to be gone. A player with no legal move must pass.","Check top colours and reserves before declaring a shutout. A single usable placement keeps the opponent playing.",["shutout","shutout2","shutout3","shutChoice"],"pin","peach"),
  readCourse("draws","Play for a draw","Spot a finish shared by both queens.","When the queens share a liberty, one landing may surround them simultaneously. Check both rings after the piece leaves its original cell.","A shared liberty only produces a draw if all five other sides of each queen remain occupied.",["draw","drawCheck"],"surround","blue"),
  readCourse("squeeze","The squeeze","Use the obligation to move.","If your opponent has legal moves, passing is unavailable. A waiting move can compel a defender to abandon a square.","Examine every reserve placement and harmless waiting move before claiming that a concession is forced.",["squeeze1","squeeze2"],"shield","peach"),
  readCourse("review","Check the opponent’s reply","Recheck your plan under pressure.","Before playing a tempting move, name the opponent's strongest immediate reply. Use the position to test the threat, especially when the clock or the opponent's reputation affects your judgement.","When surprised, recheck both queens, newly mobile attackers and changes to the top of stacks.",["psych1","psych2"],"eye","sage"),
  readCourse("mosquito","Mosquito conversion","Set up the ability you want next turn.","A ground-level Mosquito copies a neighbouring top piece. Moving from an Ant to a Beetle can trade perimeter reach for a climb on the next turn.","Recheck its neighbours after the reply. Once above ground, the Mosquito moves as a Beetle until it comes down.",["mos1","mos2"],"mix","lilac"),
  readCourse("ladybug","Ladybug routes","Reach spaces behind a gate.","A Ladybug spends two steps on top of occupied cells and its third step down into an empty one. Its route can bend.","Start with the landing space. Work back through two different occupied cells and check the height gates on the route.",["lady1","lady2"],"board","blue"),
  readCourse("pillbug","Pillbug rescue","Recognise a legal queen lift.","A Pillbug can lift an adjacent single ground-level piece over itself to another adjacent empty cell. The hive must stay connected and the route must clear height gates.","Check the previous turn before planning a lift. A piece just played by the opponent cannot immediately be relocated.",["pill1","pill2"],"shield","peach")
];
const syllabus = [
  [["win","1, 5–9, 32"],["pin","33–40"],["cover","41–46"]],
  [["opening","29–31, 223–227"],["place","27–29, 57–66, 139–148"],["hop","125–130"]],
  [["def","73–80, 219–220"],["block","19–20, 47–50"],["fill","21–24, 51–56"],["rings","20–21, 105–112, 216–217"]],
  [["strength","25–28, 67–72"],["entries","81–88, 199–208"],["tempo","89–96, 149–154"],["beetles","131–138"]],
  [["shut","97–104, 220–222"],["draws","113–118"],["squeeze","119–124"],["review","193–198"]],
  [["mosquito","155–160"],["ladybug","161–168"],["pillbug","169–192"]]
];
const Courses = syllabus.flatMap((stage,index)=>stage.map(([id,pages])=>({...topics.find(c=>c.id===id),stage:index,pages})));

function moveLesson(title,goal,hint,why,check,answers,miss) {
  return {title,goal,hint,why,check,answers,miss};
}
Object.assign(Drills,{
  elbow:moveLesson("Build an elbow","Place your queen so the first three bugs form a bend.","Open the reserve. Imagine extending the straight line between the two opening bugs.","The bend leaves an inside cell where a later bug could reconnect the branches and free your first bug.","What might filling the inside of this elbow achieve?",["Release your first bug by giving the hive a second connection.","Let either player place next to an enemy tile.","Give the queen a second move immediately."],"Trace the line through the first two bugs. Choose a queen placement off that line."),
  cOpening:moveLesson("Bring the queens closer","As Black, place the queen to make a C opening. Bend towards the side White chose.","Trace the row through the opening bugs. Both queens must lie off the row on the same side.","Both bends face the same side. The queens begin closer together and may eventually share liberties.","Why watch the space between these queens?",["A move there can affect both surrounds.","A C opening forces a draw.","The queens can slide through occupied cells."],"Use the black reserve. A C needs two bends on the same side of the central line."),
  zOpening:moveLesson("Separate the queens","As Black, place the queen to make a Z opening.","Both queens bend away from the central row. Put yours on the opposite side from White's.","The bends face opposite directions. Each side now has a different end of the hive to develop around.","What distinguishes this Z from a C?",["The queens bend to opposite sides of the opening line.","The queens stand in a single straight line.","The second player must begin with an ant."],"Choose a black queen placement off the opening line, on the opposite side from the white queen."),
  placeG:moveLesson("Aim a reserve hopper","Place a grasshopper that could jump to the marked space beside the black queen on your next turn if the line holds.","From the gold ring, look back along straight, unbroken rows. The hopper needs a legal placement at the other end.","The placement creates a jump into the marked space in one further move, provided Black leaves the line intact.","Which change would invalidate the planned landing?",["A gap opens in the line before the intended landing.","One jumped bug belongs to Black.","The line contains more than one occupied cell."],"Choose a reserve grasshopper and trace an uninterrupted line to the gold ring."),
  placeS:moveLesson("Give the spider a target","Place a reserve spider with an exact three-slide route to the marked space if Black leaves the route intact.","Work backwards from the gold ring. Count three slides with no retracing.","The spider arrives with a specific job. From its new cell the target is exactly three legal slides away.","Why count before placing the spider?",["A landing one or two slides away may be unreachable in exactly three.","A spider may wait during a slide to use its spare steps.","Placement counts as the first of its three steps."],"Trace exactly three legal slides from a reserve spider's proposed placement to the gold ring."),
  pivot:moveLesson("Change the jump line","Jump the marked hopper to a pivot from which it could jump into the gold ring on a later turn.","Trace backwards from the ring and find where one of those lines meets a legal landing for your hopper.","The first jump changes the hopper's line of approach. It can now threaten the marked space with a second jump.","What must you check after Black replies?",["Whether the hopper is free and the second jump line still works.","Whether a hopper may turn while it is in the air.","Whether both jumps cross the same number of pieces."],"Use the marked hopper and inspect its new jump lines from the proposed landing."),
  block:moveLesson("Gate the queen’s liberty","Close the entrance around the gold-ringed liberty by occupying a fifth neighbour of that space. Keep your queen in place and the marked black ant mobile elsewhere.","Follow the ant's routes to the liberty. Look for a piece that can close the entrance.","The ant can still move around the hive, but no longer has a legal path to this liberty.","Why can this empty side protect the queen?",["The marked ant cannot slide into it through the gate.","Empty cells next to a queen count twice.","A gate prevents all species from landing there."],"Leave the marked cell empty with five occupied neighbours. The ant must lose access to it while keeping other legal moves."),
  fillG:moveLesson("Free the hopper","Complete a pocket around the marked pinned hopper so it can jump.","Trace the neighbours of the hopper. Which missing contact would connect the two branches when it lifts?","The new chain around the hopper keeps the hive connected during take-off.","What changed when the pocket was completed?",["The pieces that depended on the hopper now connect around it.","The hopper can ignore the One Hive rule for a turn.","The hopper can now turn in mid-jump."],"Look for a chain of four consecutive occupied neighbours around the marked hopper that lets it jump."),
  fillB:moveLesson("Release the beetle","Complete a pocket around the marked pinned beetle and give it a legal move.","A beetle can climb only if it can lift first. Follow the chain around its cell.","The beetle's neighbours now stay connected without it. It can finally use its own movement.","Why was the climb unavailable before?",["Lifting the beetle would have split the hive.","A beetle must always start a climb beside its queen.","A beetle needs four occupied neighbours for every climb."],"Complete a chain of four around the marked beetle and check it can leave its cell."),
  ring:moveLesson("Close a useful ring","Close the six-cell loop around the gold ring. Free at least two pinned white bugs without freeing a pinned black bug.","Find the missing cell on the loop. Test whether your choice of moving piece would open a new break elsewhere.","Two or more previously pinned white pieces are now mobile. Black gets the reply, so those routes are an opportunity.","What should you count before making a ring?",["Newly mobile pieces on both sides.","Only the bugs physically moved this turn.","Only the number of empty cells inside the ring."],"Keep the marked centre empty, fill its six neighbours and check which previously pinned pieces can actually move."),
  deny:moveLesson("Choose the better pin","Pin the marked ant and keep Black from placing a reserve bug in the gold ring. Leave the ring empty.","Test the pin from different sides. Which side also touches the marked reserve entry?","Both candidate pins can restrict the ant. Your chosen square also denies Black a useful place to deploy.","Why does the empty entry now reject a black placement?",["It touches a white top piece.","Black cannot place while any black piece is pinned.","A pin blocks new pieces anywhere near the black queen."],"Check both requirements after moving. The ant must hold the hive together and the empty entry must be unavailable to Black."),
  counter:moveLesson("Defend on the way out","Move one bug to reduce the occupied sides of your queen and increase those of the black queen in the same turn. Keep both queens in place.","Start with a defender touching your queen. Look for a landing beside the other queen.","One move opens a liberty at home and takes one away at the far end. Compare the threats again after Black replies.","Why is this move efficient?",["It changes both queens' liberty counts in your favour.","It makes the moving bug permanently immune to a pin.","It forces Black to answer by moving the queen."],"Count the occupied sides of both queens after the move. Each count must change in your favour."),
  pair:moveLesson("Keep the queen covered","Keep the first beetle on the black queen. Use the second to cover the marked mobile black piece.","Find both white beetles before choosing. Which one can cover the target without releasing the queen?","The defenders now face two separate covers. Removing one beetle would release the piece beneath it.","Why use the second beetle for the new cover?",["The queen remains trapped beneath the first beetle.","Two beetles must always move on consecutive turns.","A beetle on a queen can never leave that stack."],"Leave the covering beetle on the black queen and land the other beetle on the marked piece."),
  shutout:moveLesson("Take away Black’s last move","Leave Black with no legal moves or reserve placements while both queens are still alive.","Check remaining mobile black bugs and every cell where a reserve could enter.","Black has to pass. White gets another turn and still needs to surround the queen to win.","What follows a complete shutout?",["Black passes because there is no legal move or placement.","White wins immediately.","Black may lift a pinned piece instead."],"Black retains a legal reply. Check mobile top pieces and reserve placements."),
  placeG2:moveLesson("Line up a second hopper","Place a reserve grasshopper that could jump to the gold ring beside the black queen on your next turn.","Start at the gold ring and look back along each straight row of bugs. Your placement has to sit at the far end of one row and touch only white pieces.","The new hopper has a jump that lands in the marked space. Black gets one reply to break the row or fill the cell first.","What does Black need to do to stop this hopper?",["Break the row or fill the landing space before it jumps.","Nothing. A placed hopper may jump on the same turn.","Cover the hopper with any piece, including an ant."],"Choose a reserve grasshopper and place it on a straight, unbroken row that ends in the gold ring."),
  placeS2:moveLesson("Send a spider to the queen","Place a reserve spider with an exact three-slide route to the gold ring next to the black queen.","Count back three slides from the gold ring along the edge of the hive. The spider cannot stop early or go back over a cell.","The spider's route ends in the marked liberty after exactly three slides, so it threatens to take a side next turn.","Why would a placement two slides away fail?",["A spider must use exactly three slides.","A spider moves only along rows, like a hopper.","A spider can only finish beside its own queen."],"Trace exactly three legal slides from the placement to the gold ring."),
  pivot2:moveLesson("Jump to a new line","Jump the marked hopper to a cell from which a second jump would land in the gold ring.","No current jump reaches the ring. Work back from the ring along each row and see which of those rows your hopper can land on.","After the first jump the hopper sits on a row that ends in the marked space. Black has one turn to answer.","What could stop the second jump?",["A pin on the hopper or a change to the jumped row.","Nothing. A hopper may always jump twice.","Only a black beetle landing on the ring."],"Move the marked hopper. From its landing, one of its jumps has to end in the gold ring."),
  pivot3:moveLesson("Hop round the corner","Jump the marked hopper so its next jump could land in the gold ring.","The hopper has more than one jump. Check each landing for a straight row that ends in the gold ring.","The first jump puts the hopper on a row that ends in the marked space. You still need Black to leave that row alone.","Why do two jumps sometimes beat one slide?",["Jumps ignore gates around the target cell.","Jumps may change direction in mid-air.","A hopper may jump over an empty cell."],"Move the marked hopper. Check that one of its new jumps lands in the gold ring."),
  fillG2:moveLesson("Give the hopper a pocket","Release the marked white grasshopper by completing a chain of four occupied cells around it.","The hopper holds two parts of the hive together. Find the one cell that would join them without it.","The hive now stays connected when the hopper lifts off, so it has legal jumps again.","Why could the hopper not move before?",["Lifting it would have split the hive.","A grasshopper needs a friendly bug to jump over.","Grasshoppers cannot move while a beetle is next to them."],"Fill a cell beside the marked hopper so that four neighbours in a row are occupied and it has a jump."),
  fillG3:moveLesson("Reinforce the hopper's pocket","Release the marked white grasshopper by filling the gap in the chain around it.","Count its occupied neighbours. Which empty neighbour would complete four in a row? A reserve piece can do it.","With the chain complete, the hive no longer depends on the hopper. It can jump next turn.","What does the new piece do for the hive?",["It joins the two branches the hopper was holding together.","It lets the hopper ignore the One Hive rule.","It pins a black piece next to the hopper."],"Fill a cell next to the marked hopper so four neighbours in a row are occupied and it can jump."),
  block2:moveLesson("Close the gate with a placement","Place a reserve bug so the gold-ringed liberty beside your queen has five occupied neighbours and the black ant cannot slide into it.","The gold ring has four occupied neighbours. Fill a fifth with a reserve bug where a white placement is legal.","The liberty is now behind a gate. The ant still moves, but none of its routes end in that cell.","What can still reach a gated liberty?",["A grasshopper on a row or a beetle that climbs in.","Any ant, if it starts closer to the queen.","Nothing. A gated cell is closed to every bug."],"Leave the gold ring empty with five occupied neighbours. The marked ant must lose access to it and keep other moves."),
  block3:moveLesson("Gate the liberty with a move","Move a piece so the gold-ringed liberty beside your queen has five occupied neighbours. The marked black ant must keep moving but not reach it.","Use a piece already on the board. Fill a cell next to the gold ring without moving your queen.","The marked ant can no longer slide into the liberty. Your queen keeps the empty side.","Why not just fill the liberty instead?",["An empty but unreachable side keeps the queen's breathing room.","Filling it would free the black ant.","A queen with five neighbours can always slide out."],"Leave the gold ring empty with five occupied neighbours. The marked ant must lose access to it and keep other moves."),
  twoMove1:moveLesson("Leave one gap Black cannot use","Make a move after which every Black reply still lets you surround the black queen next turn.","Take one of the two empty sides with a piece that is not needed elsewhere. Then ask whether Black can fill, block or escape from the last side.","After your move the queen has one empty side and a white beetle can reach it. If Black fills that side, Black surrounds its own queen. No black reply stops the finish.","Why can Black not just fill the last gap?",["That would surround the black queen and lose.","Black may never place next to its own queen.","A beetle on the hive can never be blocked."],"After this move Black has a reply that stops your next-turn surround, or your move gave Black the game. Check every Black reply before you commit."),
  twoMove2:moveLesson("Beetle on top, ant on the side","Your beetle already sits on the black queen. Make a move that leaves Black no way to stop a surround next turn.","The queen has two empty sides. Fill one from outside the ring. Then check what your beetle on top can do next turn.","The queen is stuck under your beetle and has one empty side left. The beetle can step down into it, and no black reply stops that.","What makes the beetle on top so strong here?",["The queen cannot move while she is covered.","A covered queen counts as surrounded.","Black cannot move any piece while the queen is covered."],"After this move Black has a reply that stops your next-turn surround, or your move gave Black the game. Check every Black reply before you commit."),
  twoMove3:moveLesson("One fills, one finishes","Make a move that leaves Black no defence against a surround next turn.","The black queen has two empty sides. Fill one with a piece whose departure does not open another side, and keep a second piece aimed at the other.","Whatever Black does, a white piece can still land on the queen's last empty side next turn.","What must you check before a two-move finish?",["Every Black reply, including queen moves, blocks and pins.","Only whether the black queen can move.","Only the number of white pieces next to the queen."],"After this move Black has a reply that stops your next-turn surround, or your move gave Black the game. Check every Black reply before you commit."),
  def6:moveLesson("Make room for the queen","Black threatens to fill your queen's last empty side. Stop every immediate Black surround.","Your queen cannot slide. Look at the white bugs touching her. Moving one of them away gives her a second empty side.","Your queen now has two empty sides. Black can fill only one this turn.","Why does moving a white neighbour away defend?",["Black would need two moves to fill two sides.","White pieces next to your queen never count for a surround.","It forces Black to move its queen."],"Black still has a move that completes the surround of your queen, or your move did it. Count her empty sides after your move."),
  def7:moveLesson("Step away from your own queen","Several black bugs can reach your queen's last empty side. Stop every immediate surround.","Blocking one attacker leaves the others. Count how many empty sides your queen will have after each move.","Your queen now has two open sides and no black piece can fill both in one move.","Why is blocking one attacker not enough here?",["Three different black pieces can reach the last side.","Blocked attackers can always jump.","Black would get two moves in a row."],"Black still has a move that completes the surround of your queen, or your move did it. Count her empty sides after your move."),
  def8:moveLesson("Stop the ant","A black ant can reach your queen's last empty side. Stop every immediate Black surround.","There are two kinds of defence: open a second side by moving a white neighbour away, or pin or cut off the ant. Black has no other finisher.","After your move no black piece can complete the surround this turn.","What did your defence take away?",["Black's only move into your queen's last side.","Black's right to move the ant at all, for the rest of the game.","Every black placement on the board."],"Black still has a move that completes the surround of your queen, or your move did it. Find the black piece that can reach the last side."),
  win4:{title:"Run the ant round",goal:"Surround the black queen in one move. Keep her five occupied sides filled.",hint:"Only one empty side is left. Find a white bug that is not touching her and can slide all the way there.",why:"The ant came from outside the ring, so none of the queen's five occupied sides opened up.",check:"Why use an ant that is not touching the queen?",answers:["Moving a neighbour away would open its old side.","Ants can only move next to the enemy queen.","Only ants can complete a surround."]},
  win5:{title:"The long jump",goal:"Surround the black queen in one move with a jump.",hint:"Follow straight rows to the last empty side. A row may run through both queens.",why:"The grasshopper jumped a row of four bugs, including both queens, and landed on the last empty side.",check:"Does it matter whose bugs the hopper jumps over?",answers:["No. It jumps any unbroken row, either colour.","Yes. It may only jump its own bugs.","Yes. It may not jump over a queen."]},
  win6:{title:"Three steps to the queen",goal:"Surround the black queen with a spider that walks exactly three slides.",hint:"Count three slides along the edge to the last empty side. No stopping early and no going back.",why:"The spider reached the last empty side in exactly three slides, and the other five sides stayed filled.",check:"Why can't the spider stop after two slides?",answers:["A spider moves exactly three slides.","A spider must touch a queen after each slide.","A spider may only stop next to an enemy bug."]},
  win7:{title:"Beetle steps in",goal:"Surround the black queen in one move.",hint:"Look at the bugs next to the last empty side. Which one is not touching the queen yet?",why:"The beetle stepped into the last empty side without leaving any other side of the queen.",check:"What made the beetle the right finisher?",answers:["It reached the gap without leaving a side of the queen.","Beetles always win when next to a queen.","Only beetles can enter a gap next to a queen."]},
  win8:{title:"The queen finishes",goal:"Surround the black queen in one move. Every other bug is the wrong choice here.",hint:"Do not forget your own queen. She slides one cell, like any other bug's step.",why:"Your queen slid into the last empty side. Your own queen can surround hers.",check:"Can your own queen take the last side?",answers:["Yes. Any bug of either colour fills a side.","No. Queens may never touch.","Only if your queen is also surrounded."]},
  pin4:{title:"Pin the queen",goal:"Pin the black queen so she cannot move. Lifting her must split the hive.",hint:"Find an empty cell that touches only the black queen. A bug there would hang off her.",why:"Your ant now hangs off the black queen. If she moved, the ant would be cut off, so she is stuck.",check:"Why is a pinned queen good for the attacker?",answers:["She cannot run from the pieces surrounding her.","She is already surrounded.","Black loses a turn each time."]},
  pin5:{title:"Spider pin",goal:"Pin the marked black grasshopper by making it the hive's only link to your piece.",hint:"Your spider walks exactly three slides. Find where it would hang off the grasshopper alone.",why:"The spider's only contact with the hive is the grasshopper. Lifting the grasshopper would split the hive.",check:"What does the pin depend on?",answers:["The spider touching no other bug.","The spider being next to the black queen.","The grasshopper having no row to jump."]},
  pin6:{title:"Jump into a pin",goal:"Pin the marked black spider before it can walk.",hint:"A grasshopper can land far from where it started. Check each landing: what would it touch?",why:"The grasshopper landed where its only neighbour is the spider. The spider can no longer lift.",check:"Why does the landing pin the spider?",answers:["The grasshopper's only contact is the spider.","Spiders cannot move next to a grasshopper.","The spider has fewer than three empty cells near it."]},
  pin7:{title:"Pin the beetle first",goal:"Pin the marked black beetle so it cannot climb or step.",hint:"A beetle can climb over gates, but it still cannot lift if that splits the hive.",why:"Your ant hangs off the beetle. Lifting the beetle, even to climb, would cut the ant off.",check:"Can the pinned beetle climb out?",answers:["No. Every move starts by lifting it.","Yes. Climbing ignores the One Hive rule.","Yes, if it climbs onto a white bug."]},
  pin8:{title:"Catch the free ant",goal:"Pin the marked black ant, which can reach many cells right now.",hint:"Look for an empty cell that touches the ant and nothing else.",why:"Your ant now depends on the black ant for contact. The black ant is pinned.",check:"What would release the black ant?",answers:["Your ant moving away, or another bug joining your ant to the hive.","Black placing any piece anywhere.","Black moving its queen."]},
  cover4:{title:"Beetle on the queen",goal:"Climb onto the black queen with a beetle.",hint:"Your beetle is on top of a stack. A beetle can step from one stack straight onto another bug.",why:"The black queen is stuck under your beetle. The stack now counts as white for placement.",check:"What can the covered queen do?",answers:["Nothing until the beetle leaves.","Slide out from under the beetle.","Climb on top of the beetle."]},
  cover5:{title:"Cover the spider",goal:"Use a beetle to cover the marked black spider.",hint:"Find a white beetle next to the spider.",why:"Only the top bug of a stack moves. The spider is frozen while your beetle stays on it.",check:"Does the spider still count next to its queen?",answers:["Yes. It still fills its cell, it just cannot move.","No. Covered bugs are removed.","Only if the beetle is black."]},
  cover6:{title:"Cover the grasshopper",goal:"Use a beetle to cover the marked black grasshopper.",hint:"Find the white beetle one step away from the grasshopper.",why:"The grasshopper is under your beetle and cannot jump.",check:"When can the grasshopper jump again?",answers:["Once the beetle moves off it.","At once, by jumping the beetle.","After one Black pass."]},
  cover7:{title:"Free your queen's stack",goal:"A black beetle is sitting on your queen. Climb onto that beetle with your own beetle.",hint:"Your beetle is up on a stack next to your queen. It can step onto another stack.",why:"The black beetle is now covered and cannot move. Your beetle is on top of the stack.",check:"What did covering the black beetle achieve?",answers:["The black beetle can no longer move.","Your queen can now move.","The black beetle is removed from the game."]},
  def4:{title:"Escape the beetle",goal:"Move your queen to a cell no black beetle can climb onto next turn.",hint:"Your queen has two slides. For each, check every black beetle's one-step moves.",why:"No black beetle can reach your queen's new cell in one move.",check:"Why does the beetle threat matter?",answers:["A beetle on your queen stops her moving.","A beetle on your queen wins at once.","A covered queen counts as surrounded."]},
  def5:{title:"Out of the beetle's reach",goal:"Move your queen so no black beetle can climb onto her next turn.",hint:"Test both queen slides. For each, check every black beetle's one-step moves, including climbs.",why:"Your queen is out of range of every black beetle for one turn.",check:"What did the escape buy?",answers:["One Black turn with no beetle cover.","Permanent safety from beetles.","A free extra move."]},
  // Drills batch 2. Facts in the text were read off the engine with study-work/batch2-pick.cjs.
  trap1:moveLesson("Shut the queen's door","The black queen can slide into either of her two empty sides. Fill one so she cannot move at all. Do not cover or pin her.","Her two empty sides are next to each other. Once one is filled, what stands on both sides of the other?","Your ant took one exit. The last empty side now has occupied cells on both flanks, so it is a gate and she cannot slide in. She is still on top and lifting her would not split the hive: the gate alone holds her.","Why can't the black queen move now?",["Her last empty side is behind a gate.","Lifting her would split the hive.","A queen cannot move next to a white ant."],"The black queen can still slide, or she is covered or pinned. Leave her on top and free to lift, with every empty side gated."),
  trap2:moveLesson("Gate her from afar","Make the black queen unable to move without covering or pinning her.","She has two empty sides and can reach both. Your ant can run round the hive to either one.","Whichever side your ant fills, the other is left between two occupied cells. The queen cannot squeeze through, so she is frozen while every rule still lets her lift.","What kind of restriction holds the queen here?",["A gate: she cannot slide into her only empty side.","A pin: lifting her would split the hive.","A cover: a beetle is on top of her."],"The black queen still has a legal slide, or you pinned or covered her. Use a gate: fill a side so the remaining empty ones are closed."),
  trap3:moveLesson("One cell closes two gates","The black queen has three empty sides. Make her unable to move with a single ant move. Do not cover or pin her.","Only two of her empty sides are exits. Find the one empty cell that sits beside both of them.","Your ant filled the cell next to both of her exits. Each remaining empty side now has occupied cells on both flanks, so the queen has no slide even with two empty sides.","The queen still has two empty sides. Why is she stuck?",["Both are gates: each has occupied cells on both flanks.","Two empty sides are never enough to move.","White's ant is touching her, so she cannot move."],"The black queen can still slide through one of her empty sides. Look for the cell that flanks both of her exits."),
  trap4:moveLesson("Freeze the defender queen","Leave the black queen with no legal move. Keep her uncovered and unpinned.","She has two empty sides next to each other. More than one of your bugs can reach them: a spider walk or an ant run will do.","Filling either empty side leaves the other gated, so she cannot slide. A frozen queen cannot run from the next attack, and you have not had to spend a beetle on her.","What does freezing the queen with a gate save you?",["A beetle: you do not need to cover her.","A tempo: Black must pass next turn.","Your queen: she can no longer be surrounded."],"The black queen can still slide, or you covered or pinned her. Fill one of her two empty sides so the other becomes a gate."),
  replace1:moveLesson("Hand the pin to a second ant","Your ant pins the marked black ant. Take over the pin with another bug so your first ant could leave without freeing it.","Find an empty cell that touches the marked ant and your pinning ant but nothing else. A bug there hangs off the same black ant.","Your second ant now hangs off the black ant too. If the first ant leaves, the black ant still holds the second one to the hive, so it stays pinned. The cost: this ant left a side of the black queen. Ingersoll warns that a pin replacement spends tempo (p. 35).","What can your first ant do now?",["Leave, and the black ant stays pinned.","Nothing: moving it would free the black ant.","Climb onto the black ant to cover it."],"The marked black ant is not pinned twice over yet. If your first ant left now, it could move. Put a second bug where it hangs off the same black ant."),
  replace2:moveLesson("Keep the queen pinned","Your ant pins the black queen. Bring another bug in so the queen stays pinned even if that ant leaves.","Look for a cell next to the black queen and your pinning ant that touches nothing else. A long ant run can reach it.","Your new ant hangs off the black queen beside the first one, so lifting the queen would still split the hive. The first ant is free for other work, and the queen now has one more occupied side.","Why does the pin survive if the first ant leaves?",["The new ant also depends on the queen for contact.","Two white ants next to a queen always pin her.","A queen can never move once she has four neighbours."],"The black queen is still pinned only by your first ant. Place a second bug where it, too, would hang off the queen."),
  replace3:moveLesson("The classic hopper replacement","Your ant pins the marked black ant. Jump a grasshopper in to take over the pin, so the ant is free.","This is the hopper pin replacement from the book. Find the jump that lands next to both the marked ant and your pinning ant, touching nothing else.","Your grasshopper now hangs off the black ant as well. The pin no longer depends on your ant, which can join the attack. An ant is worth more as an attacker than as a pin holder.","Which bug is doing the pinning now?",["Both, so either one could leave.","Only the grasshopper.","Neither: the black ant is gated, not pinned."],"The marked ant is still pinned by your ant alone. Jump a grasshopper to a cell where it hangs off the same black ant."),
  replace4:moveLesson("Free the ant that holds the spider","Your ant pins the marked black spider. Take over the pin with another bug so your ant could leave.","Find the empty cell beside both the black spider and your pinning ant. Nothing else should touch it.","The new ant hangs off the black spider next to the old one. Either white ant can now leave and the spider stays pinned. Black is left with only ten legal moves.","Why bother replacing a pin that already works?",["It frees an ant for a more important job.","A pin held by one bug ends after one turn.","It lets the spider move again."],"The black spider is still held only by your first ant. Place another bug so it also hangs off the spider."),
  unpin1:moveLesson("Release the spider","Your marked spider is pinned. Free it by moving a bug that depends on it away to a cell that does not touch it.","Lift the spider in your mind. Which bug would be cut off? Move that bug somewhere else.","The grasshopper that hung off your spider has jumped away. Lifting the spider no longer splits the hive, so it can walk again.","Why could the spider not move before?",["A bug of yours depended on it for contact with the hive.","Spiders cannot move before turn 6.","It had fewer than two empty neighbours."],"The marked spider is still stuck. Move a bug that touches it to a cell away from it, so the spider no longer holds that bug to the hive."),
  unpin2:moveLesson("Move the bug, free the spider","The marked spider is pinned. Free it by moving the bug it holds up to a cell away from it.","Find the bug that touches the spider and would be cut off if the spider lifted. Where else could it go?","Your ant ran from the spider's side to a new cell. Nothing depends on the spider now, so it can move. Ingersoll calls this releasing a pin (p. 36).","What released the pin?",["The bug that depended on the spider moved away.","The spider gained a fourth neighbour.","Black's pieces were moved away from it."],"The marked spider is still stuck. Move a bug that touches it to a cell that does not, so the spider stops holding it up."),
  unpin3:moveLesson("Untangle the hoppers","Your marked grasshopper is pinned. Free it by jumping the bug it holds up to a cell away from it.","Lift the marked hopper in your mind. One bug would be left alone. Find a jump that takes it somewhere useful.","The hopper at the end of the line jumped away, so the marked hopper no longer links it to the hive. It is free to jump again.","Why did moving a different bug free the marked one?",["The marked hopper no longer holds that bug to the hive.","Grasshoppers can always jump once a neighbour moves.","The marked hopper now has a pocket around it."],"The marked grasshopper is still stuck. Move a bug that touches it to a cell that does not touch it."),
  fillA1:moveLesson("Release the ant","Your marked ant is pinned. Fill the gap beside it so its neighbours form a chain of four in a row, and it can move.","Look at the ant's occupied neighbours. Which empty neighbour joins them into one unbroken chain?","Your second ant filled the gap. The pinned ant's neighbours now touch each other, so lifting it keeps the hive in one piece. This is the pin release from the book (p. 36), done here with a second ant.","Why can the ant move after the fill?",["Its neighbours are joined, so lifting it does not split the hive.","A fill always adds a new jump line.","Black has to move a piece off it first."],"The marked ant is still pinned, or the move does not touch it. Fill the empty cell beside it that completes four occupied neighbours in a row."),
  fillA2:moveLesson("Fill the elbow","Free your marked ant by filling the cell beside it that completes a pocket.","The ant sits where two parts of the hive meet. Find the empty neighbour that connects them.","The new ant closes the chain around the pinned one. The two branches the ant was holding together now touch directly, so it can leave.","What does the filling ant do for the hive?",["It connects the branches the pinned ant was holding together.","It pins a black bug in place of your ant.","It covers the pinned ant so it can move."],"The marked ant is still pinned. Fill the empty cell beside it that joins its neighbours into four in a row."),
  fillA3:moveLesson("Slide round to free the ant","Free your marked ant by completing a pocket around it.","One of your ants already touches the marked ant. A short slide round it can close the chain.","Your ant slid to the other side of the marked ant. Now four of its neighbours are in a row, so lifting it no longer splits the hive.","After the fill, which bug should you check next?",["The freed ant: does it now have a useful route?","The filling ant: it is pinned for good.","The black queen: she is now surrounded."],"The marked ant is still pinned. Look for a move that fills the gap in the chain around it."),
  twoMove4:moveLesson("Two sides, two turns","The black queen has two empty sides. Make a move after which every Black reply still lets you surround her next turn.","Your queen is already beside hers. Run an ant into one of the empty sides. Then ask: can Black ever cover the last one?","Your ant took one of the two empty sides. Black has 23 replies, and every one of them leaves you a move into her last side.","Why is this a forced win in two?",["Every Black reply still leaves you a surround.","Black has no legal reply at all.","The black queen is already surrounded."],"After this move Black has a reply that stops the surround next turn. Look for a move that leaves no defence."),
  twoMove5:moveLesson("The quiet spider","Make a move that leaves Black no defence against a surround next turn. The winning move does not touch the black queen.","Count Black's legal replies after each candidate. One spider walk leaves Black almost nothing to do.","After your spider's walk Black has only two legal moves, and each one lets you surround the queen next turn. A quiet move can be stronger than a direct one.","What made the spider move decisive?",["It left Black only replies that lose.","It filled the queen's fifth side.","It pinned the black queen."],"After this move Black has a reply that stops the surround next turn. Look for a move that takes away Black's useful replies."),
  twoMove6:moveLesson("Step off the stack","Make a move after which Black cannot stop a surround next turn.","Your beetle sits on top of your own ant. It can step off into one of the black queen's empty sides.","Your beetle stepped down beside the black queen, so she has one empty side left. The ant it was sitting on stays where it was, and every Black reply leaves you a way to fill the last side.","Why does the beetle leaving its stack not open a gap?",["The ant underneath stays in its cell.","Beetles always leave a copy behind.","The stack was not next to the queen."],"After this move Black has a reply that stops the surround next turn. Look for a move that leaves no defence."),
  def9:moveLesson("Open a second side","Black threatens to jump into your queen's last empty side. Stop every immediate Black surround.","Moving your queen does not help here. Which white bug next to her can walk away?","Your spider walked away from the queen, so she has two empty sides. Black can fill only one of them this turn.","Why does opening a side defend against the jump?",["Black needs two moves to fill two empty sides.","A grasshopper cannot jump next to a spider.","The queen can now slide away."],"Black can still fill your queen's last empty side next turn. Moving the queen does not help: look at the white bugs beside her."),
  def10:moveLesson("Walk the spider out","A black ant can reach your queen's last empty side. Stop every immediate Black surround.","Your queen is crowded with your own bugs. One of them can walk away and open a second side.","Your spider left the queen's side, so she has two empty sides. Black can fill one, not both, in one turn.","Why is moving your own bug a defence?",["It gives the queen a second empty side.","It blocks the black ant's route.","It pins the black ant."],"Black can still fill your queen's last empty side next turn. Moving the queen does not help: open a second side instead."),
  def11:moveLesson("Two gaps are too many","A black grasshopper can jump into your queen's last empty side. Stop every immediate Black surround.","Moving the queen does not help. Your spider beside her can walk away.","Your spider walked off, so your queen has two empty sides. Black can fill one this turn, which gives you a turn to answer.","What did the defence give your queen?",["A second empty side.","A new escape slide.","A beetle on top of her."],"Black can still fill your queen's last empty side next turn. Moving the queen does not help: open a second side instead."),
  counter2:moveLesson("Spider off your queen, onto hers","Move one bug to reduce the occupied sides of your queen and increase those of the black queen in the same turn.","Look at the bugs touching your queen. Which one can walk to the black queen?","Your spider left your queen's side and arrived beside the black queen. One move changed both counts: yours went down and hers went up.","Why is this better than a simple defensive move?",["It defends and attacks in the same turn.","It surrounds the black queen.","It pins the black queen."],"This move does not lower your queen's count and raise the black queen's at the same time. Start with a bug touching your queen."),
  counter3:moveLesson("Switch sides with one walk","Move one bug so your queen has fewer occupied sides and the black queen has more.","A spider beside your queen can walk three slides. Where would it end up?","Your spider walked from your queen to the black queen. Your queen has more room and the black queen has less.","How many turns did this counterattack cost?",["One: the same move defended and attacked.","Two: one to leave and one to arrive.","None: it was a free move."],"This move does not lower your queen's count and raise the black queen's at the same time. Start with a bug touching your queen."),
  shutout2:moveLesson("Pin the last mover","Black has a single legal move left. Leave Black with no legal move or placement.","Only one black bug can move. A white bug that hangs off it alone would pin it.","Your ant now hangs off the only mobile black bug, so lifting it would split the hive. Black has no move and no placement, and must pass.","What does Black do next turn?",["Pass: no legal move or placement is left.","Place a reserve bug anywhere.","Move the queen."],"Black still has a legal move or placement after this. Find the one black bug that can move and pin it."),
  shutout3:moveLesson("Pin the queen, close the entries","Black has queen moves and three placement cells. Leave Black with no legal move or placement with one move.","The three placement cells and the queen's exits are all near the black queen. A cell that touches only her might do both jobs.","Your ant hangs off the black queen, so she is pinned. The ant also takes one of the placement cells and touches the other two, so none of them is legal for Black. Black must pass.","Why did one ant remove the placements too?",["A placement may not touch a white bug.","Pinning the queen removes all placements.","Black has no reserve left."],"Black still has a legal move or placement after this. One cell next to the queen pins her and touches every placement cell."),
  pair2:moveLesson("Cover the black beetle","Your first beetle is on the black queen. Use the second to cover the marked black beetle.","The black beetle sits on a stack beside your queen. Your second beetle can climb straight onto it.","Your second beetle covers the black beetle, so it can no longer climb onto your queen, which it could reach this turn. The first beetle still holds the black queen, and Black has very few moves left.","Why cover the beetle rather than any other bug?",["It could climb onto your queen next turn.","Beetles are worth more points.","It was the only black bug that could move."],"Keep your first beetle on the black queen and climb onto the marked black beetle with the second one."),
  pair3:moveLesson("Cover the free hopper","Your first beetle is on the black queen. Use the second to cover the marked black grasshopper.","Find your other beetle. It is one step from the marked hopper.","The grasshopper is under your second beetle and cannot jump. The first beetle still holds the black queen.","What job does each beetle have now?",["One holds the queen, one holds the defender.","Both attack the black queen.","Both defend your queen."],"Keep your first beetle on the black queen and climb onto the marked black grasshopper with the second one."),
  draw:moveLesson("Take the shared last liberty","Finish with both queens surrounded in the same move.","Check which empty cell belongs to both rings. The moving piece must leave the other occupied sides intact.","Both queens lose their sixth liberty on the same move, which ends the game in a draw.","What made this landing a draw?",["Both queens were fully surrounded after the move.","The queens touched while both were covered.","The moving piece belonged to the side that was behind."],"Check the six neighbours of both queens after lifting the moving piece and after landing.")
});

